import json

# Load the full registry node definition
with open('/tmp/ixp_birth_cert_registry.json') as f:
    d = json.load(f)
reg_node = d['Data']['Node']

# Derive inputs from inputDefaults (per impl.md rules)
idef = reg_node['inputDefaults']
model_blob = idef['model']
# modelName is null → use modelDisplayName per Authoring rule #1
model_name = model_blob.get('modelName') or model_blob.get('modelDisplayName')
model_blob_copy = dict(model_blob)
model_blob_copy['modelName'] = model_name  # fix null

NODE_TYPE = reg_node['nodeType']
IXP_NODE_ID = "classifyAndExtractForm"

# End node definition (from registry get output above)
end_def = {
    "nodeType": "core.control.end",
    "version": "1.0",
    "category": "control-flow",
    "description": "Mark the end of a workflow path",
    "tags": ["control-flow", "end", "finish", "complete"],
    "sortOrder": 20,
    "display": {
        "label": "End",
        "icon": "circle-check",
        "shape": "circle"
    },
    "handleConfiguration": [
        {
            "position": "left",
            "handles": [
                {"id": "input", "type": "target", "handleType": "input"}
            ]
        }
    ],
    "model": {"type": "bpmn:EndEvent"}
}

# Existing manual trigger definition (from existing flow)
manual_trigger_def = {
    "nodeType": "core.trigger.manual",
    "version": "1.0",
    "category": "trigger",
    "description": "Start workflow manually",
    "tags": ["trigger", "start", "manual"],
