                {
                    "id": "output",
                    "type": "source",
                    "handleType": "output",
                    "showButton": True,
                    "constraints": {"forbiddenTargetCategories": ["trigger"]}
                }
            ],
            "visible": True
        }
    ],
    "model": {
        "type": "bpmn:StartEvent",
        "entryPointId": True
    },
    "outputDefinition": {
        "output": {
            "type": "object",
            "description": "Data passed when manually triggering the workflow.",
            "source": "null",
            "var": "output"
        }
    },
    "toolbarExtensions": {
        "design": {
            "actions": [
                {"id": "change-trigger-type", "icon": "square-mouse-pointer", "label": "Change trigger type"}
            ]
        }
    }
}

flow = {
    "id": "53ff63f1-8f95-4377-812f-fc622e7d471d",
    "version": "1.8",
    "name": "FormsClassify",
    "variables": {
        "globals": [
            {
                "id": "pdfFile",
                "name": "pdfFile",
                "direction": "in",
                "type": "string",
                "description": "Path or URL to the incoming PDF form to classify and extract"
            }
        ],
        "nodes": [
            {
                "nodeId": "start",
                "outputs": [{"var": "output", "id": "startOutput"}]
            },
            {
                "nodeId": IXP_NODE_ID,
                "outputs": [
                    {"var": "output", "id": "ixpOutput"},
                    {"var": "error", "id": "ixpError"}
                ]
            }
        ]
    },
    "nodes": [
        {
            "id": "start",
            "type": "core.trigger.manual",
            "typeVersion": "1.0",
            "display": {"label": "Manual trigger"},
            "inputs": {
                "entryPointId": "e0096e56-f0ab-48a1-a6c7-df39e6baee6a",
                "isDefaultEntryPoint": True
            }
        },
        {
            "id": IXP_NODE_ID,
            "type": NODE_TYPE,
            "display": {"label": "Classify & Extract PDF Form"},
            "inputs": {
                "model": model_blob_copy,
                "modelName": model_name,
                "projectName": idef.get('projectName'),
                "folderKey": idef.get('folderKey'),
                "folderName": idef.get('folderName'),
                "versionTag": "",
                "pageRange": "",
                "fileRef": "=js:$vars.pdfFile"
            },
            "outputs": {
                "output": reg_node['outputDefinition']['output'],
                "error": reg_node['outputDefinition']['error']
            }
        },
        {
            "id": "end1",
            "type": "core.control.end",
            "typeVersion": "1.0",
            "display": {"label": "End"},
            "inputs": {}
        }
    ],
    "edges": [
        {
            "id": "edge_start_to_ixp",
            "source": "start",
